"""Real launcher configure-only migration; never launches a host."""
from pathlib import Path
import argparse,json,plistlib,subprocess,tempfile,uuid
parser=argparse.ArgumentParser();parser.add_argument('--app',type=Path,required=True);args=parser.parse_args();source=Path(__file__).resolve().parent;work=source.parents[3]/'work/scoped-storage';checks={}
with tempfile.TemporaryDirectory(prefix='extend-storage-migration-') as directory:
 root=Path(directory).resolve();app=root/'Migration Test.app';subprocess.run(['ditto',str(args.app.resolve()),str(app)],check=True);domain='io.opensv2.storage-migration.p'+uuid.uuid4().hex;infoPath=app/'Contents/Info.plist';info=plistlib.loads(infoPath.read_bytes());info['CFBundleIdentifier']=domain;infoPath.write_bytes(plistlib.dumps(info));subprocess.run(['codesign','--force','--sign','-',str(app)],check=True,capture_output=True);exe=app/'Contents/MacOS/ExtendLoader'
 seed=root/'seed';seed.mkdir(mode=0o700);state=seed/'plugin-data/example.state';state.mkdir(parents=True,mode=0o700);(state/'value').write_bytes(b'original plugin state');(state/'value').chmod(0o600);settings={'schema':1,'sourceApplication':'/Applications/Synthesizer V Studio 2 Pro.app','dataMode':'independent','dataDirectory':str(seed),'hostDataNamespace':True};(seed/'settings.json').write_text(json.dumps(settings))
 try:
  subprocess.run(['defaults','write',domain,'loaderDataDirectory',str(seed)],check=True);target=root/'target';p=subprocess.run([str(exe),'--data-dir',str(target),'--configure-only'],capture_output=True,text=True,timeout=15);checks['newDirectoryMigrationSucceeded']=p.returncode==0;checks['scopedDataCopied']=(target/'plugin-data/example.state/value').read_bytes()==b'original plugin state';checks['sourcePreserved']=(state/'value').read_bytes()==b'original plugin state';checks['dataModePreserved']=json.loads((target/'settings.json').read_text())['dataMode']=='independent'
  (target/'plugin-data/example.state/value').write_bytes(b'profile specific');subprocess.run(['defaults','write',domain,'loaderDataDirectory',str(seed)],check=True);p=subprocess.run([str(exe),'--data-dir',str(target),'--configure-only'],capture_output=True,text=True,timeout=15);checks['existingProfileSelectedWithoutMerge']=p.returncode==0 and (target/'plugin-data/example.state/value').read_bytes()==b'profile specific'
  conflict=root/'conflict';(conflict/'plugin-data').mkdir(parents=True,mode=0o700);(conflict/'plugin-data/keep').write_bytes(b'keep');subprocess.run(['defaults','write',domain,'loaderDataDirectory',str(seed)],check=True);p=subprocess.run([str(exe),'--data-dir',str(conflict),'--configure-only'],capture_output=True,text=True,timeout=15);checks['conflictingDataPreserved']=p.returncode!=0 and (conflict/'plugin-data/keep').read_bytes()==b'keep' and not (conflict/'settings.json').exists();checks['noHostRuntimeCreated']=not (target/'runtimes').exists() and not (seed/'runtimes').exists()
 finally:subprocess.run(['defaults','delete',domain],capture_output=True)
report={'checks':checks,'passed':all(checks.values()),'scope':'Actual copied launcher with unique preferences domain, configure-only data migration and conflict handling. No host launch, account read or original configuration change.'};(work/'migration-results.json').write_text(json.dumps(report,indent=2));print(json.dumps(report,indent=2));assert report['passed']
